  "patches": [
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D1",
        "text": "Idempotency keys are scoped to the partner; a blank or missing Idempotency-Key is treated as no key and creates a new shipment each time.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D2",
        "text": "Requests without an Idempotency-Key create a new shipment and charge (legacy behavior). Partners can enable a flag to require the key.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D3",
        "text": "Idempotency keys from rejected requests (4xx responses) are not stored, allowing a corrected retry with the same key.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D4",
