        "text": "Parcel shipments must not exceed 25,000 g; heavier items must use the pallet endpoint (/v1/pallets).",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D6",
        "text": "Pallet shipments require weight_g between 25,001 and 1,000,000 g inclusive; otherwise 422 PALLET_WEIGHT_OUT_OF_RANGE.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
