18	export function createWebhookDispatcher({
19	  retryDelaysMs = DEFAULT_RETRY_DELAYS_MS,
20	  log = () => {},
21	} = {}) {
22	  const pending = new Set();
23	  let generation = 0;
24	
25	  async function attempt(webhook, rawBody, signature) {
26	    try {
27	      const response = await fetch(webhook.url, {
28	        method: "POST",
29	        headers: {
30	          "Content-Type": "application/json",
31	          "User-Agent": "Parcelly-Webhooks/1.0",
32	          [SIGNATURE_HEADER]: signature,
33	        },
34	        body: rawBody,
35	        signal: AbortSignal.timeout(ATTEMPT_TIMEOUT_MS),
36	      });
37	      return response.ok;
38	    } catch {
39	      return false;
40	    }
41	  }
42	
43	  async function deliver(webhook, event, startedIn) {
44	    const rawBody = JSON.stringify(event);
45	    const signature = signPayload(webhook.secret, rawBody);
46	    for (let index = 0; index <= retryDelaysMs.length; index += 1) {
47	      if (index > 0) {
48	        await sleep(retryDelaysMs[index - 1]);
49	      }
50	      if (generation !== startedIn) {
51	        return;
52	      }
53	      if (await attempt(webhook, rawBody, signature)) {
54	        return;
55	      }
56	    }
57	    log(`webhook ${event.event} for ${event.shipment_id} not delivered to ${webhook.url}`);
58	  }
59	
60	  return {
61	    dispatch(webhook, event) {
62	      const task = deliver(webhook, event, generation).finally(() => pending.delete(task));
63	      pending.add(task);
64	      return task;
65	    },
66	
67	    async idle() {
68	      while (pending.size > 0) {
69	        await Promise.allSettled([...pending]);
70	      }
