81	
82	  router.post("/webhooks", (request, response) => {
83	    validateWebhookRegistration(request.body);
84	    partners.setWebhook(request.partner, request.body);
85	    response.status(201).json({ url: request.body.url, events: [STATUS_CHANGED_EVENT] });
86	  });
