{
  "message": "Adding consumer-side setup, scenarios covering consumer decisions (phone normalization, address parsing, weight conversion, idempotency key usage, webhook handling, error handling, sandbox restriction), and an additional e2e scenario for the full order-to-delivery flow with webhook handling.",
  "patches": [
    {
      "op": "add",
      "path": "/setup/consumer",
      "value": [
        {
          "do": {
            "party": "consumer",
            "action": "reset"
          }
        },
        {
          "do": {
            "party": "consumer",
            "action": "seed_orders",
            "args": {
              "count": 13
            }
          }
        }
      ]
    },
    {
      "op": "add",
      "path": "/scenarios/-",
      "value": {
        "id": "S2",
        "title": "Consumer normalizes various UK phone formats to E.164 +447XXXXXXXXX",
        "side": "consumer",
        "covers": [
          "D26"
        ],
        "steps": [
          {
            "do": {
              "party": "consumer",
              "action": "normalize_phone",
              "args": {
                "input": "07700 900200"
              }
            },
            "expect": {
              "match": {
                "result": "+447700900200"
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "normalize_phone",
              "args": {
                "input": "+447700900200"
              }
            },
            "expect": {
              "match": {
                "result": "+447700900200"
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "normalize_phone",
              "args": {
                "input": "0044 7700-900200"
              }
            },
            "expect": {
              "match": {
                "result": "+447700900200"
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "normalize_phone",
              "args": {
                "input": "(+44) 7700-900345"
              }
            },
            "expect": {
              "match": {
                "result": "+447700900345"
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "normalize_phone",
              "args": {
                "input": "447700900567"
              }
            },
            "expect": {
              "match": {
                "result": "+447700900567"
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "normalize_phone",
              "args": {
                "input": "07700-900890"
              }
            },
            "expect": {
              "match": {
                "result": "+447700900890"
              }
            }
          }
        ]
      }
    },
    {
      "op": "add",
      "path": "/scenarios/-",
      "value": {
        "id": "S3",
        "title": "Consumer parses free-text address into structured fields",
        "side": "consumer",
        "covers": [
          "D27"
        ],
        "steps": [
          {
            "do": {
              "party": "consumer",
              "action": "parse_address",
              "args": {
                "address_line": "5 Long Street, London, E1 6AN"
              }
            },
            "expect": {
              "match": {
                "street": "Long Street",
                "building": "5",
                "postcode": "E1 6AN",
                "city": "London",
                "country": "GB"
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "parse_address",
              "args": {
                "address_line": "Behind the old mill, London"
              }
            },
            "expect": {
              "match": {
                "incomplete": true,
                "missing_fields": [
                  "postcode",
                  "building"
                ]
              }
            }
          }
        ]
      }
    },
    {
      "op": "add",
      "path": "/scenarios/-",
      "value": {
        "id": "S4",
        "title": "Consumer converts kg to grams and routes to parcel vs pallet endpoint",
        "side": "consumer",
        "covers": [
          "D28"
        ],
        "steps": [
          {
            "do": {
              "party": "consumer",
              "action": "calculate_shipment",
              "args": {
                "items": [
                  {
                    "unit_weight_kg": "0.300",
                    "quantity": 1
                  }
                ]
              }
            },
            "expect": {
              "match": {
                "weight_g": 300,
                "endpoint": "parcel"
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "calculate_shipment",
              "args": {
                "items": [
                  {
                    "unit_weight_kg": "27.000",
                    "quantity": 1
                  }
                ]
              }
            },
            "expect": {
              "match": {
                "weight_g": 27000,
                "endpoint": "pallet"
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "calculate_shipment",
              "args": {
                "items": [
                  {
                    "unit_weight_kg": "0.500",
                    "quantity": 2
                  },
                  {
                    "unit_weight_kg": "1.250",
                    "quantity": 1
                  }
                ]
              }
            },
            "expect": {
              "match": {
                "weight_g": 2250,
                "endpoint": "parcel"
              }
            }
          }
        ]
      }
    },
    {
      "op": "add",
      "path": "/scenarios/-",
      "value": {
        "id": "S5",
        "title": "Consumer uses order ID as Idempotency-Key for shipment creation",
        "side": "consumer",
        "covers": [
          "D29"
        ],
        "steps": [
          {
            "do": {
              "party": "consumer",
              "action": "create_shipment_request",
              "args": {
                "order_id": "ORD-1001",
                "receiver": {
                  "name": "John Smith",
                  "phone": "+447700900200",
                  "address": {
                    "street": "Long Street",
                    "building": "5",
                    "postcode": "E1 6AN",
                    "city": "London",
                    "country": "GB"
                  }
                },
                "parcel": {
                  "weight_g": 300,
                  "size": "A"
                }
              }
            },
            "expect": {
              "match": {
                "headers.Idempotency-Key": "ORD-1001"
              }
            }
          }
        ]
      }
    },
    {
      "op": "add",
      "path": "/scenarios/-",
      "value": {
        "id": "S6",
        "title": "Consumer verifies webhook signature and returns 200 for valid, 401 for invalid",
        "side": "consumer",
        "covers": [
          "D30",
          "D36"
        ],
        "steps": [
          {
            "do": {
              "party": "consumer",
              "action": "verify_webhook",
              "args": {
                "body": "{\"event\":\"shipment.status_changed\",\"shipment_id\":\"shp_1\",\"reference\":\"ORD-1001\",\"status\":\"COLLECTED\",\"occurred_at\":\"2026-10-06T10:00:00Z\"}",
                "signature": "sha256={{hmac_sha256(body, secrets.webhook_secret)}}",
                "secret": "{{secrets.webhook_secret}}"
              }
            },
            "expect": {
              "match": {
                "valid": true,
                "response_status": 200
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "verify_webhook",
              "args": {
                "body": "{\"event\":\"shipment.status_changed\",\"shipment_id\":\"shp_1\",\"reference\":\"ORD-1001\",\"status\":\"COLLECTED\",\"occurred_at\":\"2026-10-06T10:00:00Z\"}",
                "signature": "sha256=invalid_signature",
                "secret": "{{secrets.webhook_secret}}"
              }
            },
            "expect": {
              "match": {
                "valid": false,
                "response_status": 401
              }
            }
          }
        ]
      }
    },
    {
      "op": "add",
      "path": "/scenarios/-",
      "value": {
        "id": "S7",
        "title": "Consumer handles provider validation errors by logging and marking for manual review",
        "side": "consumer",
        "covers": [
          "D31"
        ],
        "steps": [
          {
            "do": {
              "party": "consumer",
              "action": "handle_provider_error",
              "args": {
                "error_code": "POSTCODE_CITY_MISMATCH",
                "order_id": "ORD-1005"
              }
            },
            "expect": {
              "match": {
                "action": "manual_review",
                "retry": false,
                "logged": true
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "handle_provider_error",
              "args": {
                "error_code": "SIZE_WEIGHT_MISMATCH",
