def _create_shipment_handler(order: Order) -> None:
    """Create a shipment with Parcelly when an order is paid, unless manual review."""
    if order.manual_review:
        logger.info(f"Order {order.id} marked for manual review, skipping shipment creation")
        return

    # Determine service based on weight in grams
    weight_g = int(round(order.weight_kg * 1000))
    if weight_g <= 25000:
        service = "parcel"
        # Size mapping: A <= 5000g, B 5001-15000g, C 15001-25000g
        if weight_g <= 5000:
            size = "A"
        elif weight_g <= 15000:
            size = "B"
        else:
            size = "C"
        parcel_data = {"weight_g": weight_g, "size": size}
        endpoint = "/v1/shipments"
    else:
        service = "pallet"
        # Pallet weight must be >= 25001 and <= 1000000 (already validated by weight_g > 25000)
        pallet_data = {"weight_g": weight_g, "pallet_type": "EUR"}
        endpoint = "/v1/pallets"

    # Build receiver dict
    receiver = {
        "name": order.customer_name,
        "phone": order.phone,
        "address": {
            "street": order.street,
            "building": order.building,
            "postcode": order.postcode,
            "city": order.city,
            "country": "GB",
        },
    }

    # Prepare request
    base_url = os.getenv("PARCELLY_BASE_URL")
    if not base_url:
        logger.error("PARCELLY_BASE_URL not set")
        order.manual_review = True
        return
    api_key = os.getenv("PARCELLY_API_KEY")
    if not api_key:
        logger.error("PARCELLY_API_KEY not set")
        order.manual_review = True
        return

    url = f"{base_url.rstrip('/')}{endpoint}"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Idempotency-Key": order.id,  # D29
    }
    if service == "parcel":
        body = {
            "reference": order.id,
            "receiver": receiver,
