          "description": "Sent when a parcel shipment changes status",
          "direction": "provider_to_consumer",
          "request": {
            "method": "POST",
            "url": "${CONSUMER_WEBHOOK_URL}",
            "headers": {
              "X-Parcelly-Signature": {
                "required": true,
                "pattern": "^sha256=[0-9a-f]{64}$"
              }
            },
            "body": {
              "$ref": "#/schemas/ShipmentStatusChanged"
            }
          },
          "signature": {
            "algorithm": "hmac-sha256",
            "header": "X-Parcelly-Signature",
            "format": "sha256={hex}",
            "over": "raw_body",
            "secret": "webhook_secret"
          },
          "consumer_responses": {
            "valid_signature": 200,
            "invalid_signature": 401
          }
        },
        "pallet_status_changed": {
          "description": "Sent when a pallet shipment changes status",
          "direction": "provider_to_consumer",
