    {
      "op": "add",
      "path": "/decisions",
      "value": [
        {
          "id": "D1",
          "text": "Receiver phone must be UK mobile in E.164 format +447XXXXXXXXX (regex ^\\+447\\d{9}$). Provider rejects with 422 INVALID_PHONE.",
          "owner": "provider"
        },
        {
          "id": "D2",
          "text": "Receiver postcode must be UK format uppercase with exactly one space (regex ^[A-Z]{1,2}\\d[A-Z\\d]? \\d[A-Z]{2}$). Provider rejects with 422 INVALID_POSTCODE.",
          "owner": "provider"
        },
        {
          "id": "D3",
          "text": "Receiver country must be GB (only GB accepted). Provider rejects other codes with 422 INVALID_REQUEST.",
          "owner": "provider"
        },
        {
          "id": "D4",
          "text": "Parcel weight_g must be >=1 g. Parcel size must be A, B, or C. Provider validates size matches weight_g (size A: 1-1000g, B: 1001-2000g, C: 2001-30000g). Mismatch returns 422 SIZE_WEIGHT_MISMATCH.",
          "owner": "provider"
        },
        {
          "id": "D5",
          "text": "Pallet weight_g must be 25001–1000000 g (25.001 kg – 1000 kg). Pallet type must be EUR. Out of range returns 422 PALLET_WEIGHT_OUT_OF_RANGE; wrong type returns 422 PALLET_TYPE_INVALID.",
          "owner": "provider"
        },
        {
          "id": "D6",
          "text": "Reference is required (1-64 chars) on every create_shipment and create_pallet call. Missing reference returns 422 REFERENCE_REQUIRED.",
          "owner": "provider"
        },
        {
          "id": "D7",
          "text": "Idempotency-Key header is optional on create_shipment and create_pallet. When provided, identical key + same payload returns the original shipment/pallet (201). When omitted or blank, a new shipment is created each call.",
          "owner": "provider"
        },
        {
          "id": "D8",
          "text": "Authorization header required on all consumer_to_provider calls. Missing or invalid returns 401 UNAUTHORIZED.",
          "owner": "provider"
        },
        {
          "id": "D9",
          "text": "Webhook signatures use HMAC-SHA256 over raw body, header X-Parcelly-Signature with format sha256={hex}. Consumer must verify and return 200 for valid, 401 for invalid/missing.",
          "owner": "provider"
        },
        {
          "id": "D10",
          "text": "Webhook secret is per-partner, configured at registration (register_webhook). Secret length 1-256 chars. Provider signs every webhook with that secret.",
          "owner": "provider"
        },
        {
          "id": "D11",
          "text": "Shipment status enum: CREATED, COLLECTED, IN_TRANSIT, DELIVERED, RETURNED. Pallet status enum identical. Webhook events: shipment.status_changed and pallet.status_changed.",
          "owner": "provider"
        },
        {
          "id": "D12",
          "text": "Error codes used: INVALID_REQUEST (400), UNAUTHORIZED (401), INVALID_PHONE (422), INVALID_POSTCODE (422), WEIGHT_LIMIT_EXCEEDED (422), SIZE_WEIGHT_MISMATCH (422), POSTCODE_CITY_MISMATCH (422), REFERENCE_REQUIRED (422), SHIPMENT_NOT_FOUND (404), PALLET_WEIGHT_OUT_OF_RANGE (422), PALLET_TYPE_INVALID (422), PALLET_NOT_FOUND (404). All error bodies follow Error schema {code, message}.",
          "owner": "provider"
        }
      ]
    },
