      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D4",
        "text": "Postcode area (outward code) must match the provided city. Mismatch returns 422 POSTCODE_CITY_MISMATCH.",
        "owner": "provider"
      }
    },
