      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D5",
        "text": "Receiver phone must match E.164 format ^\\+447\\d{9}$. Invalid format returns 422 INVALID_PHONE.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D6",
        "text": "Postcode must be uppercase, exactly one space, pattern ^[A-Z]{1,2}\\d[A-Z\\d]? \\d[A-Z]{2}$. Invalid format returns 422 INVALID_POSTCODE.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D7",
        "text": "Country must be GB. Any other value returns 400 INVALID_REQUEST.",
        "owner": "provider"
