        "id": "D10",
        "text": "Webhook signature: HMAC-SHA256 over raw request body, header X-Parcelly-Signature, format sha256={hex}, secret webhook_secret per partner.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
