    receiver_phone: str,
    receiver_address: Dict[str, Any],
    parcel_weight_g: Optional[int] = None,
    parcel_size: Optional[str] = None,
    pallet_weight_g: Optional[int] = None,
    idempotency_key: Optional[str] = None,
) -> Dict[str, Any]:
    """Create a shipment (parcel or pallet) with Parcelly."""
    if parcel_weight_g is not None and parcel_size is not None:
        # Parcel shipment
        shipment_type = "parcel"
        body = {
            "reference": reference,
            "receiver": {
                "name": receiver_name,
                "phone": receiver_phone,
                "address": receiver_address,
            },
            "parcel": {
                "weight_g": parcel_weight_g,
                "size": parcel_size,
            },
