8	export function createPartnerRegistry() {
9	  const partners = new Map();
10	  const partnersByApiKey = new Map();
11	  let counter = 0;
12	
13	  return {
14	    create({ name, apiKey, flags = {} }) {
15	      const key = apiKey ?? generateApiKey();
16	      if (partnersByApiKey.has(key)) {
