18	      }
19	      counter += 1;
20	      const partner = {
21	        id: `prt_${counter}`,
22	        name,
23	        apiKey: key,
24	        webhook: null,
25	        flags: { ...flags },
26	      };
27	      partners.set(partner.id, partner);
28	      partnersByApiKey.set(key, partner);
29	      return partner;
30	    },
31	
32	    get(id) {
33	      return partners.get(id) ?? null;
