{
  "message": "Adding consumer e2e scenarios for paid→shipped→delivered flow with webhook handling and warehouse manual confirmation, plus pallet shipment for >25kg cargo bike.",
  "patches": [
    {
      "op": "replace",
      "path": "/scenarios/0",
      "value": {
        "id": "E1",
        "title": "Paid order creates parcel shipment, webhook delivers, warehouse confirms delivered",
        "side": "consumer",
        "covers": [
          "D12",
          "D16",
          "D17",
          "D18",
          "D19",
          "D21",
          "H4",
          "create_shipment",
          "shipment_status_changed"
        ],
        "steps": [
          {
            "do": {
              "party": "provider",
              "action": "reset"
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "reset"
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "create_order",
              "args": {
                "customer_name": "John Smith",
                "phone": "07700 900200",
                "address_line": "Long Street 5, Flat 3, E1 6AN, London",
                "items": [
                  {
                    "sku": "BOOK-120",
                    "quantity": 1,
                    "unit_price_pence": 1299,
                    "unit_weight_kg": 1.2
                  }
                ]
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "pay_order",
              "args": {
                "order_id": "{{ctx.order_id}}"
              }
            }
          },
          {
            "send": {
              "operation": "create_shipment",
              "headers": {
                "Authorization": "Bearer {{ctx.api_key}}",
                "Idempotency-Key": "{{ctx.order_id}}"
              },
              "body": {
                "reference": "{{ctx.order_id}}",
                "receiver": {
                  "name": "John Smith",
                  "phone": "+447700900200",
                  "address": {
                    "street": "Long Street",
                    "building": "5",
                    "flat": "3",
                    "postcode": "E1 6AN",
                    "city": "London",
                    "country": "GB"
                  }
                },
                "parcel": {
                  "weight_g": 1200,
                  "size": "A"
                }
              }
            },
            "expect": {
              "status": 201,
              "match": {
                "body.status": "CREATED",
                "body.service": "parcel",
                "body.reference": "{{ctx.order_id}}",
                "body.parcel.weight_g": 1200,
                "body.parcel.size": "A",
                "body.price_pence": 1299
              }
            },
            "capture": {
              "shipment_id": "$.id"
            }
          },
          {
            "do": {
              "party": "provider",
              "action": "advance_shipment",
              "args": {
                "shipment_id": "{{ctx.shipment_id}}",
                "to": "COLLECTED"
              }
            }
          },
          {
            "expect_emitted": {
              "webhook": "shipment_status_changed",
              "signature": "valid",
              "within_s": 5,
              "match": {
                "body.status": "COLLECTED",
                "body.shipment_id": "{{ctx.shipment_id}}",
                "body.reference": "{{ctx.order_id}}"
              }
            }
          },
          {
            "do": {
              "party": "provider",
              "action": "advance_shipment",
              "args": {
                "shipment_id": "{{ctx.shipment_id}}",
                "to": "IN_TRANSIT"
              }
            }
          },
          {
            "expect_emitted": {
              "webhook": "shipment_status_changed",
              "signature": "valid",
              "within_s": 5,
              "match": {
                "body.status": "IN_TRANSIT",
                "body.shipment_id": "{{ctx.shipment_id}}",
                "body.reference": "{{ctx.order_id}}"
              }
            }
          },
          {
            "do": {
              "party": "provider",
              "action": "advance_shipment",
              "args": {
                "shipment_id": "{{ctx.shipment_id}}",
                "to": "DELIVERED"
              }
            }
          },
          {
            "expect_emitted": {
              "webhook": "shipment_status_changed",
              "signature": "valid",
              "within_s": 5,
              "match": {
                "body.status": "DELIVERED",
                "body.shipment_id": "{{ctx.shipment_id}}",
                "body.reference": "{{ctx.order_id}}"
              }
            }
          },
          {
            "expect_state": {
              "party": "consumer",
              "query": "order",
              "match": {
                "status": "paid"
              },
              "eventually": {
                "timeout_s": 10,
                "interval_s": 0.5
              }
            }
          },
          {
            "do": {
              "party": "consumer",
              "action": "warehouse_confirm_delivered",
              "args": {
                "order_id": "{{ctx.order_id}}"
              }
            }
          },
          {
            "expect_state": {
              "party": "consumer",
              "query": "order",
              "match": {
                "status": "delivered"
              }
            }
          }
        ]
      }
    },
