  "message": "Consumer (Spokes) turn 10: Fixing consumer-side issues identified by provider in Round 9.",
  "patches": [
    {
      "op": "replace",
      "path": "/decisions",
      "value": [
        { "id": "D1", "rule": "Parcel size must match weight_g: A (1-5000g), B (5001-15000g), C (15001-25000g). Mismatch returns 422 SIZE_WEIGHT_MISMATCH.", "owner": "provider" },
        { "id": "D2", "rule": "Pallet weight_g must be 25001-1000000g. Outside range returns 422 PALLET_WEIGHT_OUT_OF_RANGE.", "owner": "provider" },
        { "id": "D3", "rule": "Postcode area (first 1-2 letters) must match receiver.address.city. Mismatch returns 422 POSTCODE_CITY_MISMATCH.", "owner": "provider" },
        { "id": "D4", "rule": "Idempotency-Key longer than 255 characters returns 400 INVALID_IDEMPOTENCY_KEY. Blank or missing key creates a new shipment each time.", "owner": "provider" },
        { "id": "D5", "rule": "Webhook shipment.status_changed emitted only on genuine status transitions (CREATED→COLLECTED, COLLECTED→IN_TRANSIT, IN_TRANSIT→DELIVERED, IN_TRANSIT→RETURNED). Creating a shipment (status CREATED) does NOT emit a webhook. Re-setting the same status does NOT emit a webhook.", "owner": "provider" },
        { "id": "D6", "rule": "Tracking numbers follow format PCL<n>GB for parcel service and PAL<n>GB for pallet service.", "owner": "provider" },
        { "id": "D7", "rule": "Parcel pricing: size A = 1299 pence, B = 1599 pence, C = 1999 pence. Pallet pricing: EUR pallet = 8900 pence. Price returned in price_pence field.", "owner": "provider" },
        { "id": "D8", "rule": "Receiver phone must match ^\\+447\\d{9}$ (UK mobile E.164). Invalid format returns 422 INVALID_PHONE.", "owner": "provider" },
        { "id": "D9", "rule": "Receiver address postcode must match ^[A-Z]{1,2}\\d[A-Z\\d]? \\d[A-Z]{2}$ (uppercase, exactly one space). Invalid format returns 422 INVALID_POSTCODE.", "owner": "provider" },
        { "id": "D10", "rule": "Receiver address country must be GB. Any other value returns 400 INVALID_REQUEST.", "owner": "provider" },
        { "id": "D11", "rule": "Parcelly sends X-Parcelly-Signature: sha256=<hex> computed as HMAC-SHA256(raw_body, webhook_secret). Consumer verifies signature over exact raw request bytes before processing. Invalid signature → return 401.", "owner": "provider" },
        { "id": "D12", "rule": "Idempotency keys are scoped to partner. A 4xx response does not store the key, allowing corrected retry with same key.", "owner": "provider" },
        { "id": "D13", "rule": "Reference field max length 64 characters. Receiver name max 120. Address street max 120, building max 20, flat max 20, city max 80.", "owner": "provider" },
        { "id": "D14", "rule": "Pallet type must be EUR. Any other value returns 422 INVALID_PALLET_TYPE.", "owner": "provider" },
        { "id": "D15", "rule": "Spokes stores address as single free-text line. Parcelly requires structured fields: street, building, postcode, city, country=GB. Consumer extracts postcode (UK format, last token), city (token before postcode), street+building from remainder. If postcode/city cannot be extracted, fail fast.", "owner": "consumer" },
        { "id": "D16", "rule": "Spokes stores weight_kg as float. Parcelly requires weight_g integer (grams). Consumer converts: weight_g = round(weight_kg * 1000). Parcel threshold: weight_g ≤ 25000 → parcel (size A/B/C by weight tier); weight_g > 25000 → pallet endpoint. Cargo bikes >25kg use pallet endpoint.", "owner": "consumer" },
        { "id": "D17", "rule": "Parcel size tier derived from weight_g: A ≤ 5000g, B 5001-15000g, C 15001-25000g. Consumer selects size field accordingly.", "owner": "consumer" },
        { "id": "D18", "rule": "Spokes uses handler-based idempotency. Parcelly uses Idempotency-Key header (≤255 chars, scoped per partner). Consumer sends Spokes order reference as Idempotency-Key on shipment creation.", "owner": "consumer" },
        { "id": "D19", "rule": "Parcelly sends X-Parcelly-Signature: sha256=<hex> computed as HMAC-SHA256(raw_body, webhook_secret). Consumer verifies signature over exact raw request bytes before processing. Invalid signature → return 401.", "owner": "consumer" },
        { "id": "D20", "rule": "Order paid event handlers (ORDER_PAID_HANDLERS) must be idempotent: payment gateway may retry confirmations (second call finds order already paid, keeps original paid_at, calls handlers again). Exception in a handler is logged and does not undo payment; remaining handlers still run.", "owner": "consumer" },
        { "id": "D21", "rule": "When order status changes from pending to paid, Spokes creates a Parcelly shipment (parcel or pallet based on weight_g). This happens in an ORDER_PAID_HANDLER and must be idempotent (uses order reference as Idempotency-Key).", "owner": "consumer" },
        { "id": "D22", "rule": "Spokes order status lifecycle: pending → paid → shipped → delivered, with cancelled as a branch from pending via support. No automated carrier status; shipped and delivered set manually by warehouse team.", "owner": "consumer" },
        { "id": "D23", "rule": "POST /orders/{id}/pay returns 409 ORDER_NOT_PAYABLE if order status not in (pending, paid). Duplicate payment confirmation does not change paid_at; original timestamp preserved.", "owner": "consumer" },
        { "id": "D24", "rule": "Spokes stores phone numbers in free-text format (e.g., '07700 900200', '+44 7700 900234'). Parcelly requires E.164 +447XXXXXXXXX. Consumer normalizes by stripping non-digits, ensuring leading +447, validating 11 digits after +44.", "owner": "consumer" },
        { "id": "H1", "rule": "For cargo bikes >25kg (e.g., Spokes Haul 2 at 27kg/31.5kg): use Parcelly's pallet endpoint for >25kg orders.", "owner": "consumer" },
        { "id": "H2", "rule": "For incomplete addresses (e.g., 'Behind the old mill, London' with no clear postcode): fail shipment creation (return error to order paid handler).", "owner": "consumer" }
