          { "expect_emitted": { "webhook": "shipment_status_changed", "signature": "valid", "within_s": 5, "match": { "body.status": "COLLECTED", "body.shipment_id": "{{ctx.shipment_id}}" } } },
          { "do": { "party": "provider", "action": "advance_shipment", "args": { "shipment_id": "{{ctx.shipment_id}}", "to": "IN_TRANSIT" } } },
          { "expect_emitted": { "webhook": "shipment_status_changed", "signature": "valid", "within_s": 5, "match": { "body.status": "IN_TRANSIT", "body.shipment_id": "{{ctx.shipment_id}}" } } },
