34	  app.disable("x-powered-by");
35	  app.locals.parcelly = { partners, shipments, webhooks };
36	
37	  if (log) {
38	    app.use(requestLogger);
39	  }
40	  app.use(express.json());
41	
42	  app.get("/health", (request, response) => {
43	    response.json({ status: "ok", sandbox });
44	  });
45	  app.use(
46	    "/v1",
47	    requirePartner(partners),
48	    createShipmentsRouter({ shipments }),
49	    createWebhooksRouter({ partners }),
