6	export function createSandboxRouter({ partners, shipments, webhooks }) {
7	  const router = express.Router();
8	
9	  router.post("/reset", (request, response) => {
10	      webhooks.reset();
11	      shipments.reset();
12	      partners.reset();
13	
14	      const apiKey = process.env.PARTNER_API_KEY;
15	      const webhookUrl = process.env.WEBHOOK_URL;
16	      const webhookSecret = process.env.WEBHOOK_SECRET;
17	      let partnerInfo = null;
18	      if (apiKey) {
19	          // Ensure a partner exists with the provided API key
20	          let partner = partners.findByApiKey(apiKey);
21	          if (!partner) {
22	              partner = partners.create({
23	                  name: "spokes",
24	                  apiKey: apiKey,
25	              });
26	          }
27	          // If webhook URL and secret are provided, set the webhook for the partner
28	          if (webhookUrl && webhookSecret) {
29	              partners.setWebhook(partner, { url: webhookUrl, secret: webhookSecret });
30	          }
31	          partnerInfo = { partner_id: partner.id, api_key: partner.apiKey };
32	      }
33	
34	      if (partnerInfo) {
35	          response.json({ status: "reset", ...partnerInfo });
36	      } else {
37	          response.json({ status: "reset" });
38	      }
39	  });
40	
41	  router.post("/partners", (request, response) => {
42	    validateSandboxPartner(request.body);
43	    const partner = partners.create({
44	      name: request.body.name,
45	      apiKey: request.body.api_key,
46	      flags: request.body.flags,
47	    });
48	    response.status(201).json({ partner_id: partner.id, api_key: partner.apiKey });
49	  });
50	
51	  const advance = (findShipment) => (request, response) => {
52	    validateAdvance(request.body);
53	    const shipment = findShipment(request.params);
54	    if (shipment === null) {
55	      throw new ApiError(404, "SHIPMENT_NOT_FOUND", "Shipment not found");
56	    }
57	    response.json(serializeShipment(shipments.advance(shipment, request.body.to)));
58	  };
59	
60	  router.post(
61	    "/shipments/by-reference/:reference/advance",
62	    advance(({ reference }) => shipments.findLatestByReference(reference)),
63	  );
64	  router.post(
65	    "/shipments/:id/advance",
66	    advance(({ id }) => shipments.get(id)),
67	  );
68	
69	  router.get("/charges", (request, response) => {
70	    const reference = request.query.reference;
71	    if (typeof reference !== "string" || reference === "") {
72	      throw new ApiError(400, "REFERENCE_REQUIRED", "Query parameter 'reference' is required");
73	    }
74	    response.json(shipments.chargesFor(reference));
75	  });
76	
77	  return router;
78	}

