156	  const match = Object.entries(SIZE_LIMITS_G).find(([, limit]) => weightG <= limit);
157	  return match ? match[0] : null;
158	}
159	
160	export function validateShipmentRequest(body) {
161	  assertSchema(validators.shipment, body);
162	  assertReceiverFormats(body.receiver);
163	  const { weight_g: weightG, size } = body.parcel;
164	  if (weightG > MAX_PARCEL_WEIGHT_G) {
165	    throw new ApiError(
166	      422,
167	      "WEIGHT_LIMIT_EXCEEDED",
168	      `Parcel weight ${weightG} g exceeds the limit of ${MAX_PARCEL_WEIGHT_G} g`,
169	    );
170	  }
171	  if (sizeForWeight(weightG) !== size) {
172	    throw new ApiError(
173	      422,
174	      "SIZE_WEIGHT_MISMATCH",
175	      `Size ${size} does not match parcel weight ${weightG} g`,
176	    );
177	  }
178	  assertPostcodeMatchesCity(body.receiver.address);
179	}
180	
181	export function validatePalletRequest(body) {
182	  assertSchema(validators.pallet, body);
183	  assertReceiverFormats(body.receiver);
184	  const weightG = body.pallet.weight_g;
185	  if (weightG < MIN_PALLET_WEIGHT_G || weightG > MAX_PALLET_WEIGHT_G) {
186	    throw new ApiError(
187	      422,
188	      "PALLET_WEIGHT_OUT_OF_RANGE",
189	      `Pallet weight must be between ${MIN_PALLET_WEIGHT_G} g and ${MAX_PALLET_WEIGHT_G} g`,
190	    );
191	  }
192	  assertPostcodeMatchesCity(body.receiver.address);
193	}
194	
195	export function validateWebhookRegistration(body) {
196	  assertSchema(validators.webhook, body);
197	  let url;
198	  try {
199	    url = new URL(body.url);
200	  } catch {
201	    url = null;
202	  }
203	  if (url === null || !["http:", "https:"].includes(url.protocol)) {
204	    throw new ApiError(400, "INVALID_WEBHOOK_URL", "Webhook url must be an absolute http(s) URL");
205	  }
206	}
207	
208	export function validateSandboxPartner(body) {
209	  assertSchema(validators.sandboxPartner, body);
210	}
211	
212	export function validateAdvance(body) {
213	  assertSchema(validators.advance, body);
214	}

