        {
          "id": "H1",
          "rule": "Order status lifecycle: pending -> paid -> shipped -> delivered, with cancelled as a branch from pending via support.",
          "source": "docs/INTERNAL.md",
          "public": false
        },
        {
          "id": "H2",
          "rule": "Payment gateway may retry confirmations (second call finds order already paid, keeps original paid_at, calls handlers again). Handlers must be idempotent.",
          "source": "docs/INTERNAL.md",
          "public": false
        },
        {
          "id": "H3",
          "rule": "shipped and delivered statuses are set manually by the warehouse team today; no automated carrier integration exists.",
          "source": "docs/INTERNAL.md",
          "public": false
        },
        {
          "id": "H4",
          "rule": "Support marks orders as cancelled and adds notes in helpdesk for parcels coming back; no automated return status.",
          "source": "docs/INTERNAL.md",
          "public": false
        },
        {
          "id": "H5",
          "rule": "Handler exception does not undo payment; remaining handlers still run.",
          "source": "app/services/order_events.py",
          "public": false
        },
        {
          "id": "H6",
          "rule": "Order is reloaded from database before response after handlers run, so handler-made changes are returned to caller.",
          "source": "app/services/order_events.py",
          "public": false
        },
        {
          "id": "H7",
          "rule": "Order number starts at 1001 and increments sequentially.",
          "source": "app/services/orders.py",
          "public": false
        },
        {
          "id": "H8",
          "rule": "weight_kg rounded to 3 decimals as sum of unit_weight_kg * quantity.",
          "source": "app/services/orders.py",
          "public": false
        },
        {
          "id": "H9",
          "rule": "total_pence calculated as sum of unit_price_pence * quantity.",
