4	function generateApiKey() {
5	  return `pk_test_${randomBytes(16).toString("hex")}`;
6	}
7	
8	export function createPartnerRegistry() {
9	  const partners = new Map();
10	  const partnersByApiKey = new Map();
11	  let counter = 0;
12	
13	  return {
14	    create({ name, apiKey, flags = {} }) {
15	      const key = apiKey ?? generateApiKey();
16	      if (partnersByApiKey.has(key)) {
17	        throw new ApiError(409, "API_KEY_TAKEN", "A partner with this API key already exists");
18	      }
19	      counter += 1;
20	      const partner = {
21	        id: `prt_${counter}`,
22	        name,
23	        apiKey: key,
24	        webhook: null,
25	        flags: { ...flags },
26	      };
27	      partners.set(partner.id, partner);
28	      partnersByApiKey.set(key, partner);
29	      return partner;
30	    },
31	
32	    get(id) {
33	      return partners.get(id) ?? null;
34	    },
35	
36	    findByApiKey(apiKey) {
37	      return partnersByApiKey.get(apiKey) ?? null;
38	    },
39	
40	    setWebhook(partner, webhook) {
41	      partner.webhook = { url: webhook.url, secret: webhook.secret };
42	    },
43	
44	    reset() {
45	      partners.clear();
46	      partnersByApiKey.clear();
47	      counter = 0;
48	    },
49	  };
50	}

