3	const BEARER_PATTERN = /^Bearer\s+(\S+)$/;
4	
5	export function requirePartner(partners) {
6	  return (request, response, next) => {
7	    const match = BEARER_PATTERN.exec(request.get("authorization") ?? "");
8	    const partner = match ? partners.findByApiKey(match[1]) : null;
9	    if (partner === null) {
10	      response.set("WWW-Authenticate", "Bearer");
11	      next(new ApiError(401, "UNAUTHORIZED", "Missing or invalid partner API key"));
12	      return;
13	    }
14	    request.partner = partner;
15	    next();
16	  };
17	}

